def emit(x):print(json.dumps(x,ensure_ascii=False).replace(PW,'[REDACTED]'),flush=True)
def get(p):return json.load(O.open(urllib.request.Request(BASE+p+Q,headers=H),timeout=12))
def fully_stopped(states,tree,blocked):return all(states.get(i,{'type':'idle'}).get('type')=='idle' or i in blocked for i in tree)
def route(t):return t in {'permission.asked','permission.updated','session.created','session.error'}
def verify():
 assert not route('message.part.updated') and not route('message.part.delta') and not route('session.status') and not route('session.idle')
 assert not fully_stopped({'p':{'type':'idle'},'c':{'type':'busy'}},{'p','c'},set())
 assert fully_stopped({'p':{'type':'idle'},'c':{'type':'idle'}},{'p','c'},set())
 for keys in [['approval','approval'],['stopped','stopped']]:assert len(set(keys))==1
verify()
