import subprocess,re,json

services=["openvela-backend.service","openvela-worker.service"]
keywords=re.compile(r"(?i)(chat|conversation|timeout|timed out|deadline|error|exception|failed|failure|redis|postgres|hikari|pool|worker|upstream|502|503|504|connection|refused|reset|broken pipe|queue|stream|sse|websocket)")
