bearer=re.compile(r'(?i)Bearer\s+[A-Za-z0-9._~+/=-]+')
longnum=re.compile(r'(?<![A-Za-z0-9])\+?\d{7,}(?![A-Za-z0-9])')
query=re.compile(r'(https?://[^\s?]+)\?[^\s]+')
def run(args):
    p=subprocess.run(args,text=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=30)
    return p.returncode,p.stdout,p.stderr
out={}
for svc in services:
    rc,show,err=run(["systemctl","show",svc,"--no-pager",
        "--property=ActiveState","--property=SubState","--property=ActiveEnterTimestamp",
        "--property=ExecMainStartTimestamp","--property=MainPID","--property=NRestarts",
        "--property=Result","--property=ExecMainStatus","--property=MemoryCurrent",
        "--property=TasksCurrent"])
    props={}
    for line in show.splitlines():
        if "=" in line:
            k,v=line.split("=",1); props[k]=v
    rcj,journal,errj=run(["journalctl","-u",svc,"--since","2 hours ago","--no-pager","-o","short-iso-precise"])
    lines=[]
    total=0
    for line in journal.splitlines():
        if keywords.search(line):
            total+=1
            line=sensitive_key.sub(lambda m: m.group(1)+"=<redacted>",line)
            line=bearer.sub("Bearer <redacted>",line)
            line=longnum.sub("<number>",line)
            line=query.sub(r"\1?<redacted>",line)
            lines.append(line[:1200])
    out[svc]={"showRc":rc,"properties":props,"journalRc":rcj,
              "matchedCount":total,"matchedTail":lines[-180:],
              "journalError":errj.strip()[:300] if rcj else ""}
print(json.dumps(out,ensure_ascii=False,indent=2))
