    repos = [r.strip() for r in args.repos.split(",")] if args.repos else list_repos()

    for repo in repos:
        master_repo = MASTER_DIR / repo
        if not master_repo.exists():
            print(f"[ERROR] master/{repo} 不存在，跳过", file=sys.stderr)
            continue

