"""Dev-first workflow: synchronize each repository including its design docs."""
import argparse
from pathlib import Path
import re
import subprocess


def git(repo, *args):
    return subprocess.run(['git', *args], cwd=repo, check=True,
                          stdout=subprocess.PIPE, stderr=subprocess.PIPE).stdout.decode().strip()


def name(value):
    if not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_-]*', value):
        raise ValueError(f'非法名称: {value}')
    return value


def clean(repo, branch):
    if git(repo, 'branch', '--show-current') != branch:
        raise ValueError(f'{repo} 未检出 {branch}')
    if git(repo, 'status', '--porcelain'):
        raise ValueError(f'{repo} 有未提交修改，停止操作')
    for state in ('MERGE_HEAD', 'CHERRY_PICK_HEAD', 'REVERT_HEAD'):
        if Path(git(repo, 'rev-parse', '--git-path', state)).is_absolute():
            path = Path(git(repo, 'rev-parse', '--git-path', state))
        else:
            path = repo / git(repo, 'rev-parse', '--git-path', state)
        if path.exists():
            raise ValueError(f'{repo} 存在未完成的 Git 操作')


def production(repo):
    branch = git(repo, 'branch', '--show-current')
    if branch not in ('master', 'main'):
        raise ValueError(f'{repo} 必须在 master/main')
    return branch


def repos_for(base, explicit, feature=None):
    available = sorted(p.name for p in (base / 'master').iterdir()
                       if (p / '.git').exists() and p.name != 'ai-skin-backend')
    repos = [name(r.strip()) for r in explicit.split(',')] if explicit else available
    for repo in repos:
        if repo == 'ai-skin-backend':
            raise ValueError('ai-skin-backend 已停维护，仅供参考')
        if repo not in available:
            raise ValueError(f'未知基座仓库: {repo}')
    if feature and not explicit:
        repos = [r for r in repos if (base / f'feature-{feature}' / r).exists()]
    if not repos:
        raise ValueError('没有匹配的维护中仓库')
    return repos


def ensure_dev(base, repo):
    master = base / 'master' / repo
    target = base / 'dev' / repo
    if target.exists():
        if git(target, 'branch', '--show-current') != 'dev':
            raise ValueError(f'{target} 不是有效 dev worktree')
        return target
    branches = git(master, 'for-each-ref', '--format=%(refname:short)', 'refs/heads', 'refs/remotes/origin').splitlines()
    target.parent.mkdir(exist_ok=True)
    if 'dev' in branches:
        git(master, 'worktree', 'add', str(target), 'dev')
    elif 'origin/dev' in branches:
        git(master, 'worktree', 'add', '--track', '-b', 'dev', str(target), 'origin/dev')
    else:
        git(master, 'worktree', 'add', '-b', 'dev', str(target), production(master))
    return target


def integrate(base, command, feature, repos):
    for repo in repos:
        master = base / 'master' / repo
        dev = base / 'dev' / repo
        if command == 'promote-dev':
            branch = production(master)
            clean(master, branch)
            clean(dev, 'dev')
            git(dev, 'pull', '--ff-only', 'origin', 'dev')
            git(master, 'pull', '--ff-only', 'origin', branch)
            git(master, 'merge-base', '--is-ancestor', branch, 'dev')
            git(master, 'merge', '--ff-only', 'dev')
            git(master, 'push', 'origin', branch)
        else:
            feature_repo = base / f'feature-{feature}' / repo
            clean(feature_repo, f'feature/{feature}')
            clean(dev, 'dev')
            git(dev, 'pull', '--ff-only', 'origin', 'dev')
            if command == 'sync-dev':
                before = git(feature_repo, 'rev-parse', 'HEAD')
                git(feature_repo, 'merge', '--no-edit', 'dev')
                changed = git(feature_repo, 'diff', '--name-only', before, 'HEAD', '--', 'docs/')
                if changed:
                    print(f'[DOCS] {repo}: 合并后请重新阅读设计变更：\n{changed}')
            else:
                git(dev, 'merge', '--no-edit', f'feature/{feature}')
                git(dev, 'push', 'origin', 'dev')
        print(f'[DONE] {command}: {repo}')


def run(base, argv):
    parser = argparse.ArgumentParser(description='dev 基线与架构同步')
    sub = parser.add_subparsers(dest='command', required=True)
    for command in ('sync-dev', 'deploy-dev'):
        p = sub.add_parser(command)
        p.add_argument('feature_name', type=name)
        p.add_argument('--repos')
    for command in ('init-dev', 'promote-dev'):
        p = sub.add_parser(command)
        p.add_argument('--repos', required=True)
    args = parser.parse_args(argv)
    try:
        feature = getattr(args, 'feature_name', None)
        repos = repos_for(base, args.repos, feature)
        if args.command == 'init-dev':
            for repo in repos:
                print(ensure_dev(base, repo))
        else:
            integrate(base, args.command, feature, repos)
    except (ValueError, OSError, subprocess.CalledProcessError) as exc:
        detail = exc.stderr.decode() if isinstance(exc, subprocess.CalledProcessError) and exc.stderr else str(exc)
        print(f'[ERROR] {detail}')
        return 1
    return 0
