   213	        for (JsonNode item : metricsNode) {
   214	            if (!item.isObject()) {
   215	                continue;
   216	            }
   217	            Map<String, Object> metric = new LinkedHashMap<>();
   218	            copy(metric, "name", item.get("name"));
   219	            copy(metric, "value", item.get("value"));
   220	            copy(metric, "unit", item.get("unit"));
   221	            out.add(metric);
   222	        }
   223	        return out;
   224	    }
