        if rtype == "python":
            if (repo_path / "pyproject.toml").exists():
                subprocess.run(["uv", "sync"], cwd=repo_path, check=True)
            elif (repo_path / "requirements.txt").exists():
                subprocess.run(["uv", "init"], cwd=repo_path, check=True)
                subprocess.run(["uv", "add", "-r", "requirements.txt"], cwd=repo_path, check=True)
        elif rtype == "java":
            if (repo_path / "pom.xml").exists():
                subprocess.run(["mvn", "clean", "compile", "-DskipTests"], cwd=repo_path, check=True)
            elif (repo_path / "build.gradle").exists() or (repo_path / "build.gradle.kts").exists():
                subprocess.run(["./gradlew", "compileJava"], cwd=repo_path, check=True)
        elif rtype == "js":
            subprocess.run(["npm", "install"], cwd=repo_path, check=True)
        else:
            return
    except subprocess.CalledProcessError:
        print(f"[WARNING] {name} 依赖自动安装失败，请进入目录手动排查修复。", file=sys.stderr)


