        raise ValueError('missing OSS config keys: ' + ','.join(missing_keys))
    if found['OSS_SMOKE_APP_ENV'] != SCOPE:
        raise ValueError('isolated OSS scope changed')
    empty = [key for key in REQUIRED if not found[key]]
    if require_complete and empty:
