    if empty:
        return found
    if not re.fullmatch(r'[a-z0-9-]+', found['MVP_A_STORAGE_OSS_REGION']):
        raise ValueError('invalid OSS region format')
    if not re.fullmatch(r'[a-z0-9-]{3,63}', found['MVP_A_STORAGE_OSS_BUCKET']):
        raise ValueError('invalid OSS bucket format')
    for key in ('MVP_A_STORAGE_OSS_SERVER_ENDPOINT', 'MVP_A_STORAGE_OSS_PUBLIC_ENDPOINT'):
        u = urlsplit(found[key])
        if u.scheme not in ('http', 'https') or not u.hostname or u.username or u.password or u.query or u.fragment or u.path not in ('', '/'):
